// ──────────────────────────── tests ──────────────────────────────────────

test('a missing order is not shippable', () => {
  eq(shippingCost(null), null);
});

test('refuses countries we do not ship to', () => {
  eq(shippingCost({ country: 'FR', weightKg: 2, subtotal: 20 }), null);
});

test('refuses freight-weight orders', () => {
  eq(shippingCost({ country: 'US', weightKg: 31, subtotal: 20 }), null);
});

test('express is a flat 25 in the US', () => {
  eq(shippingCost({ country: 'US', weightKg: 2, subtotal: 20, express: true }), 25);
});

test('express to Canada costs 35', () => {
  eq(shippingCost({ country: 'CA', weightKg: 2, subtotal: 20, express: true }), 35);
});

test('express beats free shipping', () => {
  eq(shippingCost({ country: 'US', weightKg: 2, subtotal: 500, express: true }), 25);
});

test('standard shipping is free over 100', () => {
  eq(shippingCost({ country: 'US', weightKg: 2, subtotal: 100 }), 0);
});

test('heavy standard orders cost 15, light ones 7', () => {
  eq(shippingCost({ country: 'CA', weightKg: 11, subtotal: 99 }), 15);
  eq(shippingCost({ country: 'CA', weightKg: 10, subtotal: 99 }), 7);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('subtotal sums price times quantity', () => {
  eq(subtotal(CART), 39.98);
  eq(subtotal([]), 0);
});

test('discountFor only honours the coupon it knows', () => {
  eq(discountFor(39.98, 'SAVE10'), 4);
  eq(discountFor(39.98, 'BOGUS'), 0);
  eq(discountFor(39.98, undefined), 0);
});

test('shippingFor is free over 50 or with FREESHIP', () => {
  eq(shippingFor(35.98, undefined), 5.99);
  eq(shippingFor(50, undefined), 0);
  eq(shippingFor(1, 'FREESHIP'), 0);
});

test('taxFor rounds to cents', () => {
  eq(taxFor(35.98, 0.08), 2.88);
  eq(taxFor(0, 0.08), 0);
});

test('processOrder returns every line of the summary', () => {
  eq(processOrder({ items: CART, coupon: 'SAVE10', taxRate: 0.08 }), {
    subtotal: 39.98,
    discount: 4,
    shipping: 5.99,
    tax: 2.88,
    total: 44.85,
  });
});

test('a big cart ships free and takes no discount', () => {
  eq(processOrder({ items: [{ sku: 'rug', price: 60, qty: 1 }], taxRate: 0.08 }), {
    subtotal: 60,
    discount: 0,
    shipping: 0,
    tax: 4.8,
    total: 64.8,
  });
});

test('FREESHIP zeroes shipping but not tax', () => {
  const out = processOrder({ items: CART, coupon: 'FREESHIP', taxRate: 0.1 });
  eq(out.shipping, 0);
  eq(out.discount, 0);
  eq(out.total, 43.98);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('the null logger implements the whole interface', () => {
  const log = createNullLogger();
  for (const method of ['info', 'warn', 'error']) {
    ok(typeof log[method] === 'function', `missing ${method}`);
    eq(log[method]('anything'), undefined);
  }
});

test('a successful task returns its result', () => {
  eq(runTask({ name: 'sync', run: () => 42 }, fakeLogger()), {
    ok: true,
    result: 42,
  });
});

test('a successful task logs start and done', () => {
  const log = fakeLogger();
  runTask({ name: 'sync', run: () => 42 }, log);
  eq(log.info.calls, [['start sync'], ['done sync']]);
  eq(log.error.callCount, 0);
});

test('a throwing task is caught, not propagated', () => {
  eq(runTask({ name: 'sync', run: () => { throw new Error('boom'); } }, fakeLogger()), {
    ok: false,
    error: 'boom',
  });
});

test('a throwing task logs through error, and never logs done', () => {
  const log = fakeLogger();
  runTask({ name: 'sync', run: () => { throw new Error('boom'); } }, log);
  eq(log.error.calls, [['failed sync: boom']]);
  eq(log.info.calls, [['start sync']]);
});

test('no logger at all still works', () => {
  eq(runTask({ name: 'quiet', run: () => 'ok' }), { ok: true, result: 'ok' });
  eq(runTask({ name: 'quiet', run: () => { throw new Error('x'); } }), {
    ok: false,
    error: 'x',
  });
});

// ──────────────────────────── tests ──────────────────────────────────────

test('the email notifier sends the body untouched', () => {
  eq(createNotifier('email').send('a@b.co', 'ship it'), {
    channel: 'email',
    to: 'a@b.co',
    body: 'ship it',
  });
});

test('the sms notifier truncates at 140 characters', () => {
  const long = 'x'.repeat(200);
  const record = createNotifier('sms').send('+15550100', long);
  eq(record.channel, 'sms');
  eq(record.body.length, 140);
  eq(createNotifier('sms').send('+15550100', 'short').body, 'short');
});

test('the slack notifier prefixes a bare channel name', () => {
  eq(createNotifier('slack').send('ops', 'deploy done'), {
    channel: 'slack',
    to: '#ops',
    body: 'deploy done',
  });
});

test('the slack notifier leaves an existing # alone', () => {
  eq(createNotifier('slack').send('#ops', 'deploy done').to, '#ops');
});

test('every built-in honours the same interface', () => {
  eq(notifierTypes(), ['email', 'slack', 'sms']);
  for (const type of notifierTypes()) {
    const n = createNotifier(type);
    eq(n.type, type);
    ok(typeof n.send === 'function', `${type} cannot send`);
    eq(n.send('dest', 'body').channel, type);
  }
});

test('an unknown channel is rejected by name', () => {
  createNotifier('email');
  throws(() => createNotifier('fax'), 'unknown notifier type: fax');
});

test('new channels register without editing the factory', () => {
  registerNotifier('push', () => ({
    type: 'push',
    send: (to, message) => ({ channel: 'push', to, body: message.toUpperCase() }),
  }));
  eq(createNotifier('push').send('device-1', 'hi'), {
    channel: 'push',
    to: 'device-1',
    body: 'HI',
  });
  ok(notifierTypes().includes('push'));
});

// ──────────────────────────── tests ──────────────────────────────────────

test('the regular price is just unit price times quantity', () => {
  eq(regularPrice(20, 3), 60);
  eq(regularPrice(9.99, 3), 29.97);
});

test('members save 10 percent', () => {
  eq(memberPrice(20, 3), 54);
});

test('members save 15 percent from ten units', () => {
  eq(memberPrice(20, 10), 170);
  eq(memberPrice(20, 9), 162);
});

test('the sale gives every third unit free', () => {
  eq(salePrice(20, 7), 100);
  eq(salePrice(20, 2), 40);
  eq(salePrice(20, 3), 40);
});

test('a tier name selects a strategy, unknown tiers fall back', () => {
  ok(pickPricing('member') === memberPrice);
  ok(pickPricing('sale') === salePrice);
  ok(pickPricing('regular') === regularPrice);
  ok(pickPricing('platinum-elite') === regularPrice);
});

test('the pricer quotes with the strategies it was handed', () => {
  const pricer = createPricer({ pricing: regularPrice, shipping: flatShipping });
  eq(pricer.quote(20, 3, 2), { goods: 60, shipping: 6, total: 66 });
});

test('swapping the pricing strategy needs no new pricer', () => {
  const pricer = createPricer({ pricing: regularPrice, shipping: flatShipping });
  pricer.setPricing(memberPrice);
  eq(pricer.quote(20, 3, 2), { goods: 54, shipping: 6, total: 60 });
});

test('shipping swaps on its own axis', () => {
  const pricer = createPricer({ pricing: salePrice, shipping: flatShipping });
  pricer.setShipping(byWeightShipping);
  eq(pricer.quote(20, 7, 2), { goods: 100, shipping: 5, total: 105 });
});

// ──────────────────────────── tests ──────────────────────────────────────

test('a subscriber receives the payload', () => {
  const bus = createEventBus();
  const seen = spy();
  bus.on('order:paid', seen);
  bus.emit('order:paid', { id: 7 });
  eq(seen.calls, [[{ id: 7 }]]);
});

test('emit reports how many handlers ran', () => {
  const bus = createEventBus();
  bus.on('a', spy());
  bus.on('a', spy());
  eq(bus.emit('a', 1), 2);
  eq(bus.emit('nobody-listens', 1), 0);
});

test('handlers fire in registration order', () => {
  const bus = createEventBus();
  const marks = [];
  bus.on('a', () => marks.push('first'));
  bus.on('a', () => marks.push('second'));
  bus.emit('a');
  eq(marks, ['first', 'second']);
});

test('off removes exactly one handler', () => {
  const bus = createEventBus();
  const keep = spy();
  const drop = spy();
  bus.on('a', keep);
  bus.on('a', drop);
  eq(bus.off('a', drop), true);
  bus.emit('a', 1);
  eq(keep.callCount, 1);
  eq(drop.callCount, 0);
});

test('the function returned by on unsubscribes', () => {
  const bus = createEventBus();
  const handler = spy();
  const stop = bus.on('a', handler);
  bus.emit('a');
  stop();
  bus.emit('a');
  eq(handler.callCount, 1);
});

test('a wildcard handler hears every channel, with its name', () => {
  const bus = createEventBus();
  const audit = spy();
  bus.on('*', audit);
  bus.on('order:paid', spy());
  eq(bus.emit('order:paid', { id: 1 }), 2);
  bus.emit('user:login', { id: 2 });
  eq(audit.calls, [
    [{ id: 1 }, 'order:paid'],
    [{ id: 2 }, 'user:login'],
  ]);
});

test('removing something that was never added is harmless', () => {
  const bus = createEventBus();
  const handler = spy();
  const stop = bus.on('a', handler);
  stop();
  stop();
  eq(bus.off('a', handler), false);
  ok(bus.emit('a') === 0);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('get returns the initial value', () => {
  eq(createWatchable('light').get(), 'light');
});

test('set replaces the value', () => {
  const theme = createWatchable('light');
  theme.set('dark');
  eq(theme.get(), 'dark');
});

test('watchers are called with next and previous', () => {
  const theme = createWatchable('light');
  const seen = spy();
  theme.watch(seen);
  theme.set('dark');
  eq(seen.calls, [['dark', 'light']]);
});

test('every watcher hears the change', () => {
  const count = createWatchable(0);
  const a = spy();
  const b = spy();
  count.watch(a);
  count.watch(b);
  count.set(1);
  count.set(2);
  eq(a.callCount, 2);
  eq(b.calls, [[1, 0], [2, 1]]);
});

test('setting the same value notifies nobody', () => {
  const count = createWatchable(0);
  const seen = spy();
  count.watch(seen);
  count.set(0);
  count.set(NaN);
  count.set(NaN);
  eq(seen.callCount, 1);
});

test('the function returned by watch stops that watcher only', () => {
  const count = createWatchable(0);
  const stopped = spy();
  const kept = spy();
  const stop = count.watch(stopped);
  count.watch(kept);
  stop();
  count.set(1);
  eq(stopped.callCount, 0);
  eq(kept.callCount, 1);
});

// ──────────────────────────── tests ──────────────────────────────────────

for (const provider of PROVIDERS) {
  test(`${provider.name}: charges and normalizes the receipt`, () => {
    eq(provider.make().charge({ amountCents: 2500, token: 'tok_ok' }), {
      ok: true,
      id: provider.id,
      amountCents: 2500,
    });
  });

  test(`${provider.name}: a declined card is ok:false, not a throw`, () => {
    const receipt = provider.make().charge({ amountCents: 2500, token: 'bad_token' });
    eq(receipt.ok, false);
    eq(receipt.id, null);
  });

  test(`${provider.name}: refunds a partial amount in cents`, () => {
    eq(provider.make().refund(provider.id, 1000), {
      ok: true,
      id: provider.id,
      amountCents: 1000,
    });
  });
}

test('both adapters expose the same interface', () => {
  for (const provider of PROVIDERS) {
    const adapter = provider.make();
    eq(adapter.provider, provider.name);
    ok(typeof adapter.charge === 'function');
    ok(typeof adapter.refund === 'function');
  }
});

test('caller code is identical for both providers', () => {
  const [stripe, paypal] = PROVIDERS.map((p) => settle(p.make()));
  eq(stripe.charged.amountCents, paypal.charged.amountCents);
  eq(stripe.refunded.amountCents, paypal.refunded.amountCents);
  eq([stripe.charged.ok, stripe.refunded.ok], [true, true]);
  eq([paypal.charged.ok, paypal.refunded.ok], [true, true]);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('withLogging passes the result through untouched', () => {
  eq(withLogging(add, spy())(2, 3), 5);
});

test('withLogging records the arguments and the return value', () => {
  const log = spy();
  withLogging(add, log)(2, 3);
  eq(log.calls, [
    ['call', [2, 3]],
    ['return', 5],
  ]);
});

test('withTiming reports elapsed ms from the injected clock', () => {
  const record = spy();
  const timed = withTiming(add, record, fakeClock(100, 142));
  eq(timed(2, 3), 5);
  eq(record.calls, [[42]]);
});

test('withTiming works with any arity', () => {
  const record = spy();
  const shout = withTiming((s) => s.toUpperCase(), record, fakeClock(0, 3));
  eq(shout('hi'), 'HI');
  eq(record.calls, [[3]]);
});

test('withRetry survives transient failures', async () => {
  const flaky = spy(async () => {
    if (flaky.callCount < 3) throw new Error('flap');
    return 'ok';
  });
  eq(await withRetry(flaky, 5)(), 'ok');
  eq(flaky.callCount, 3);
});

test('withRetry gives up after the last attempt and rethrows', async () => {
  const boom = spy(async () => {
    throw new Error(`nope ${boom.callCount}`);
  });
  const wrapped = withRetry(boom, 2);
  await rejects(() => wrapped(), 'nope 2');
  eq(boom.callCount, 2);
});

test('decorators compose without knowing about each other', () => {
  const log = spy();
  const record = spy();
  const wrapped = withTiming(withLogging(add, log), record, fakeClock(0, 5));
  eq(wrapped(2, 3), 5);
  eq(log.calls, [
    ['call', [2, 3]],
    ['return', 5],
  ]);
  eq(record.calls, [[5]]);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('the report is stamped with the injected clock', () => {
  const service = createReportService({
    clock: fixedClock(AT),
    random: seq(0.12345),
    store: createMemoryStore(),
  });
  eq(service.generate('u1', ROWS).createdAt, '2023-11-14T22:13:20.000Z');
});

test('the id comes from the injected random, padded to four digits', () => {
  const service = createReportService({
    clock: fixedClock(AT),
    random: seq(0.12345, 0.0007),
    store: createMemoryStore(),
  });
  eq(service.generate('u1', ROWS).id, 'RPT-1234');
  eq(service.generate('u1', ROWS).id, 'RPT-0007');
});

test('the report totals and counts the rows', () => {
  const service = createReportService({
    clock: fixedClock(AT),
    random: seq(0.5),
    store: createMemoryStore(),
  });
  const report = service.generate('u1', ROWS);
  eq(report.rowCount, 2);
  eq(report.total, 42);
  eq(report.userId, 'u1');
  eq(service.generate('u1', []).total, 0);
});

test('the report is handed to the store exactly once', () => {
  const store = { save: spy(), all: () => [] };
  const service = createReportService({
    clock: fixedClock(AT),
    random: seq(0.5),
    store,
  });
  const report = service.generate('u1', ROWS);
  eq(store.save.callCount, 1);
  ok(store.save.calls[0][0] === report, 'save got a different object');
});

test('history filters the store by user', () => {
  const service = createReportService({
    clock: fixedClock(AT),
    random: seq(0.1, 0.2, 0.3),
    store: createMemoryStore(),
  });
  service.generate('u1', ROWS);
  service.generate('u2', ROWS);
  service.generate('u1', ROWS);
  eq(service.history('u1').map((r) => r.id), ['RPT-1000', 'RPT-3000']);
  eq(service.history('nobody'), []);
});

test('a different clock gives a different report, with no globals', () => {
  const store = createMemoryStore();
  const later = createReportService({
    clock: fixedClock(AT + 86400000),
    random: seq(0.5),
    store,
  });
  eq(later.generate('u1', ROWS).createdAt, '2023-11-15T22:13:20.000Z');
});

test('the memory store keeps its array to itself', () => {
  const store = createMemoryStore();
  eq(store.all(), []);
  store.save({ id: 'a' });
  store.all().push({ id: 'sneaky' });
  eq(store.all(), [{ id: 'a' }]);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('add stores the user and assigns a sequential id', () => {
  const repo = createUserRepository();
  eq(repo.add({ name: 'Ada', email: 'ada@x.io' }), {
    id: 'u1',
    name: 'Ada',
    email: 'ada@x.io',
  });
  eq(repo.add({ name: 'Grace', email: 'grace@x.io' }).id, 'u2');
  eq(repo.count(), 2);
});

test('getById finds a user, or returns undefined', () => {
  const repo = createUserRepository();
  repo.add({ name: 'Ada', email: 'ada@x.io' });
  eq(repo.getById('u1').name, 'Ada');
  eq(repo.getById('nope'), undefined);
});

test('the repository hands out copies, not its own objects', () => {
  const repo = createUserRepository();
  const added = repo.add({ name: 'Ada', email: 'ada@x.io' });
  added.name = 'HACKED';
  const fetched = repo.getById('u1');
  fetched.name = 'ALSO HACKED';
  eq(repo.getById('u1').name, 'Ada');
});

test('find filters with a predicate', () => {
  const repo = createUserRepository();
  repo.add({ name: 'Ada', email: 'ada@x.io' });
  repo.add({ name: 'Grace', email: 'grace@x.io' });
  eq(repo.find((u) => u.name.startsWith('A')).map((u) => u.id), ['u1']);
  eq(repo.find(() => true).length, 2);
  eq(repo.find(() => false), []);
});

test('update merges a patch and leaves the rest alone', () => {
  const repo = createUserRepository();
  repo.add({ name: 'Ada', email: 'ada@x.io' });
  eq(repo.update('u1', { name: 'Ada L.' }), {
    id: 'u1',
    name: 'Ada L.',
    email: 'ada@x.io',
  });
  eq(repo.getById('u1').name, 'Ada L.');
  eq(repo.update('ghost', { name: 'x' }), undefined);
});

test('delete removes and reports whether it did', () => {
  const repo = createUserRepository();
  repo.add({ name: 'Ada', email: 'ada@x.io' });
  eq(repo.delete('u1'), true);
  eq(repo.delete('u1'), false);
  eq(repo.getById('u1'), undefined);
  eq(repo.count(), 0);
});

test('the service registers users through the repository', () => {
  const repo = createUserRepository();
  const service = createUserService(repo);
  const user = service.register('Ada', 'ada@x.io');
  eq(user.id, 'u1');
  eq(repo.count(), 1);
  eq(service.rename('u1', 'Ada L.').name, 'Ada L.');
});

test('the service enforces rules the repository knows nothing about', () => {
  const service = createUserService(createUserRepository());
  service.register('Ada', 'ada@x.io');
  throws(() => service.register('Imposter', 'ADA@X.IO'), 'email already registered');
  throws(() => service.rename('ghost', 'x'), 'no such user: ghost');
  ok(true);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('getConfig always hands back the very same object', () => {
  resetForTests();
  const first = getConfig();
  ok(first === getConfig(), 'a second instance was created');
  first.retries = 7;
  eq(getConfig().retries, 7);
});

test('it starts from the defaults', () => {
  resetForTests();
  eq(getConfig(), {
    env: 'development',
    retries: 3,
    apiUrl: 'http://localhost:3000',
  });
});

test('configure merges into the live instance and returns it', () => {
  resetForTests();
  const held = getConfig();
  const returned = configure({ retries: 5 });
  eq(held.retries, 5);
  eq(held.apiUrl, 'http://localhost:3000');
  ok(returned === held);
});

test('the logger is a singleton too', () => {
  resetForTests();
  ok(getLogger() === getLogger());
  getLogger().info('one');
  getLogger().info('two');
  eq(getLogger().lines.length, 2);
});

test('the logger reads the shared config, not a copy of it', () => {
  resetForTests();
  configure({ env: 'production' });
  getLogger().info('boot');
  eq(getLogger().lines, ['[production] boot']);
});

test('resetForTests restores the defaults', () => {
  resetForTests();
  configure({ env: 'production', retries: 99 });
  resetForTests();
  eq(getConfig().env, 'development');
  eq(getConfig().retries, 3);
});

test('resetForTests clears the logger — this is the test-pollution fix', () => {
  resetForTests();
  getLogger().info('noise from an earlier test');
  resetForTests();
  eq(getLogger().lines, []);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('a good order comes back as one receipt', () => {
  const parts = makeParts();
  eq(createCheckoutFacade(parts).place(ORDER), {
    ok: true,
    chargeId: 'ch_1',
    label: 'LBL-1',
    amountCents: 3800,
  });
});

test('every subsystem is called once, with what it needs', () => {
  const parts = makeParts();
  createCheckoutFacade(parts).place(ORDER);
  eq(parts.inventory.reserve.calls, [['mug', 2], ['tee', 1]]);
  eq(parts.payments.charge.calls, [[3800, 'tok']]);
  eq(parts.shipping.schedule.calls, [['1 Main St', ITEMS]]);
  eq(parts.inventory.release.callCount, 0);
});

test('the confirmation email names the shipping label', () => {
  const parts = makeParts();
  createCheckoutFacade(parts).place(ORDER);
  eq(parts.email.send.calls, [['ada@x.io', 'Order confirmed: LBL-1']]);
});

test('an out-of-stock item names the sku that failed', () => {
  const parts = makeParts({ inStock: (sku) => sku !== 'tee' });
  eq(createCheckoutFacade(parts).place(ORDER), {
    ok: false,
    reason: 'out-of-stock',
    sku: 'tee',
  });
});

test('out of stock releases what was already reserved and charges nothing', () => {
  const parts = makeParts({ inStock: (sku) => sku !== 'tee' });
  createCheckoutFacade(parts).place(ORDER);
  eq(parts.inventory.release.calls, [['mug', 2]]);
  eq(parts.payments.charge.callCount, 0);
  eq(parts.email.send.callCount, 0);
});

test('a declined card releases every reservation', () => {
  const parts = makeParts({ paid: false });
  eq(createCheckoutFacade(parts).place(ORDER), {
    ok: false,
    reason: 'payment-declined',
  });
  eq(parts.inventory.release.calls, [['mug', 2], ['tee', 1]]);
});

test('a declined card ships nothing and emails nobody', () => {
  const parts = makeParts({ paid: false });
  createCheckoutFacade(parts).place(ORDER);
  eq(parts.shipping.schedule.callCount, 0);
  eq(parts.email.send.callCount, 0);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('a bare query selects everything', () => {
  eq(createQuery('users').build(), {
    table: 'users',
    fields: ['*'],
    where: [],
    orderBy: [],
    limit: null,
  });
});

test('select and limit land in the descriptor', () => {
  const q = createQuery('users').select('id', 'name').limit(10).build();
  eq(q.fields, ['id', 'name']);
  eq(q.limit, 10);
  eq(createQuery('users').limit(0).build().limit, 0);
});

