// ─────────────────────────────────────────────────────────────────────────
//  02 · processOrder                                            ★★☆ core
//  concepts: decomposition · single responsibility · composition
//  run: node exercises/02-extract-function.js
// ─────────────────────────────────────────────────────────────────────────
//
//  One 60-line `processOrder` does five jobs and can only be tested from
//  the outside. Split it into four small exported functions plus one
//  composer that wires them together. Use the provided `round2` on every
//  money value so cents never drift.
//
//      subtotal(items)              → round2(sum of price × qty)
//      discountFor(sub, coupon)     → 'SAVE10' → 10% of sub, else 0
//      shippingFor(amount, coupon)  → 0 if coupon is 'FREESHIP'
//                                     0 if amount >= 50, else 5.99
//      taxFor(amount, rate)         → round2(amount × rate)
//
//      processOrder({ items, coupon, taxRate }) →
//        { subtotal, discount, shipping, tax, total }
//
//  In the composer: taxable = round2(subtotal − discount); shipping and
//  tax are both computed from `taxable`, and
//  total = round2(taxable + shipping + tax).
//
//  hint: the composer should be ~6 lines and contain no arithmetic
//  beyond one subtraction and one addition

import { test, eq } from '../../_lib/check.js';

export const round2 = (n) => Math.round(n * 100) / 100;

export function subtotal(items) {
  throw new Error('TODO');
}

export function discountFor(amount, coupon) {
  throw new Error('TODO');
}

export function shippingFor(amount, coupon) {
  throw new Error('TODO');
}

export function taxFor(amount, rate) {
  throw new Error('TODO');
}

export function processOrder(order) {
  throw new Error('TODO');
}

const CART = [
  { sku: 'mug', price: 9.99, qty: 2 },
  { sku: 'tee', price: 20, qty: 1 },
];

// ──────────────────────────── tests ──────────────────────────────────────

test('subtotal sums price times quantity', () => {
  eq(subtotal(CART), 39.98);
  eq(subtotal([]), 0);
});

test('discountFor only honours the coupon it knows', () => {
  eq(discountFor(39.98, 'SAVE10'), 4);
  eq(discountFor(39.98, 'BOGUS'), 0);
  eq(discountFor(39.98, undefined), 0);
});

test('shippingFor is free over 50 or with FREESHIP', () => {
  eq(shippingFor(35.98, undefined), 5.99);
  eq(shippingFor(50, undefined), 0);
  eq(shippingFor(1, 'FREESHIP'), 0);
});

test('taxFor rounds to cents', () => {
  eq(taxFor(35.98, 0.08), 2.88);
  eq(taxFor(0, 0.08), 0);
});

test('processOrder returns every line of the summary', () => {
  eq(processOrder({ items: CART, coupon: 'SAVE10', taxRate: 0.08 }), {
    subtotal: 39.98,
    discount: 4,
    shipping: 5.99,
    tax: 2.88,
    total: 44.85,
  });
});

test('a big cart ships free and takes no discount', () => {
  eq(processOrder({ items: [{ sku: 'rug', price: 60, qty: 1 }], taxRate: 0.08 }), {
    subtotal: 60,
    discount: 0,
    shipping: 0,
    tax: 4.8,
    total: 64.8,
  });
});

test('FREESHIP zeroes shipping but not tax', () => {
  const out = processOrder({ items: CART, coupon: 'FREESHIP', taxRate: 0.1 });
  eq(out.shipping, 0);
  eq(out.discount, 0);
  eq(out.total, 43.98);
});

jstrain/14-swe-design-patterns/02-extrac.solution:
// ─────────────────────────────────────────────────────────────────────────
//  02 · processOrder — SOLUTION                                 ★★☆ core
//  concepts: decomposition · single responsibility · composition
//  run: node solutions/02-extract-function.js
// ─────────────────────────────────────────────────────────────────────────
//
//  Walkthrough:
//  Intent — give every rule its own name so it can be read, tested and
//  changed alone. The composer becomes a table of contents: you can see
//  the whole checkout policy in six lines without reading any arithmetic.
//  Each piece is a pure function of its inputs, so the tests above pin
//  the *rules* (discount, shipping) separately from the *sequence*.
//  When NOT to use: don't extract a function you can only name after its
//  caller (`doStep2`) — that's a sign the seam is in the wrong place, and
//  a chain of one-line indirections is harder to read than the original.
//  In the wild: this is the refactor behind every "service layer" — and
//  it is what makes a Redux reducer or a pricing engine testable.
//  Classic wrong turn: rounding only at the end. Round each money value
//  as you produce it and every intermediate number stays a real price.

import { test, eq } from '../../_lib/check.js';

export const round2 = (n) => Math.round(n * 100) / 100;

export function subtotal(items) {
  return round2(items.reduce((sum, item) => sum + item.price * item.qty, 0));
}

export function discountFor(amount, coupon) {
  return coupon === 'SAVE10' ? round2(amount * 0.1) : 0;
}

export function shippingFor(amount, coupon) {
  if (coupon === 'FREESHIP') return 0;
  return amount >= 50 ? 0 : 5.99;
}

export function taxFor(amount, rate) {
  return round2(amount * rate);
}

export function processOrder(order) {
  const sub = subtotal(order.items);
  const discount = discountFor(sub, order.coupon);
  const taxable = round2(sub - discount);
  const shipping = shippingFor(taxable, order.coupon);
  const tax = taxFor(taxable, order.taxRate);
  return {
    subtotal: sub,
    discount,
    shipping,
    tax,
    total: round2(taxable + shipping + tax),
  };
}

const CART = [
  { sku: 'mug', price: 9.99, qty: 2 },
  { sku: 'tee', price: 20, qty: 1 },
];

// ──────────────────────────── tests ──────────────────────────────────────

test('subtotal sums price times quantity', () => {
  eq(subtotal(CART), 39.98);
  eq(subtotal([]), 0);
});

test('discountFor only honours the coupon it knows', () => {
  eq(discountFor(39.98, 'SAVE10'), 4);
  eq(discountFor(39.98, 'BOGUS'), 0);
  eq(discountFor(39.98, undefined), 0);
});

test('shippingFor is free over 50 or with FREESHIP', () => {
  eq(shippingFor(35.98, undefined), 5.99);
  eq(shippingFor(50, undefined), 0);
  eq(shippingFor(1, 'FREESHIP'), 0);
});

test('taxFor rounds to cents', () => {
  eq(taxFor(35.98, 0.08), 2.88);
  eq(taxFor(0, 0.08), 0);
});

test('processOrder returns every line of the summary', () => {
  eq(processOrder({ items: CART, coupon: 'SAVE10', taxRate: 0.08 }), {
    subtotal: 39.98,
    discount: 4,
    shipping: 5.99,
    tax: 2.88,
    total: 44.85,
  });
});

test('a big cart ships free and takes no discount', () => {
  eq(processOrder({ items: [{ sku: 'rug', price: 60, qty: 1 }], taxRate: 0.08 }), {
    subtotal: 60,
    discount: 0,
    shipping: 0,
    tax: 4.8,
    total: 64.8,
  });
});

test('FREESHIP zeroes shipping but not tax', () => {
  const out = processOrder({ items: CART, coupon: 'FREESHIP', taxRate: 0.1 });
  eq(out.shipping, 0);
  eq(out.discount, 0);
  eq(out.total, 43.98);
});

jstrain/14-swe-design-patterns/03-null-o.starter:
// ─────────────────────────────────────────────────────────────────────────
//  03 · null object                                         ★☆☆ warm-up
//  concepts: null object · optional collaborators · defaults
//  run: node exercises/03-null-object.js
// ─────────────────────────────────────────────────────────────────────────
//
//  `runTask` is littered with `if (logger) logger.info(...)`. Kill the
//  ifs: when no logger is passed, substitute one that implements the
//  same interface and does nothing.
//
//      createNullLogger()  → { info(), warn(), error() }  all no-ops
//
//      runTask(task, logger?)
//        logs   `start ${task.name}`               (info)
//        on ok  logs `done ${task.name}`           (info)
//               returns { ok: true, result }
//        on throw logs `failed ${task.name}: ${message}`  (error)
//               returns { ok: false, error: message }
//
//  The body of runTask must contain no `if (logger)` check anywhere.
//
//  hint: `const log = logger ?? createNullLogger();` on line one

import { test, eq, ok, spy } from '../../_lib/check.js';

export function createNullLogger() {
  throw new Error('TODO');
}

export function runTask(task, logger) {
  throw new Error('TODO');
}

const fakeLogger = () => ({ info: spy(), warn: spy(), error: spy() });

// ──────────────────────────── tests ──────────────────────────────────────

test('the null logger implements the whole interface', () => {
  const log = createNullLogger();
  for (const method of ['info', 'warn', 'error']) {
    ok(typeof log[method] === 'function', `missing ${method}`);
    eq(log[method]('anything'), undefined);
  }
});

test('a successful task returns its result', () => {
  eq(runTask({ name: 'sync', run: () => 42 }, fakeLogger()), {
    ok: true,
    result: 42,
  });
});

test('a successful task logs start and done', () => {
  const log = fakeLogger();
  runTask({ name: 'sync', run: () => 42 }, log);
  eq(log.info.calls, [['start sync'], ['done sync']]);
  eq(log.error.callCount, 0);
});

test('a throwing task is caught, not propagated', () => {
  eq(runTask({ name: 'sync', run: () => { throw new Error('boom'); } }, fakeLogger()), {
    ok: false,
    error: 'boom',
  });
});

test('a throwing task logs through error, and never logs done', () => {
  const log = fakeLogger();
  runTask({ name: 'sync', run: () => { throw new Error('boom'); } }, log);
  eq(log.error.calls, [['failed sync: boom']]);
  eq(log.info.calls, [['start sync']]);
});

test('no logger at all still works', () => {
  eq(runTask({ name: 'quiet', run: () => 'ok' }), { ok: true, result: 'ok' });
  eq(runTask({ name: 'quiet', run: () => { throw new Error('x'); } }), {
    ok: false,
    error: 'x',
  });
});

jstrain/14-swe-design-patterns/03-null-o.solution:
// ─────────────────────────────────────────────────────────────────────────
//  03 · null object — SOLUTION                              ★☆☆ warm-up
//  concepts: null object · optional collaborators · defaults
//  run: node solutions/03-null-object.js
// ─────────────────────────────────────────────────────────────────────────
//
//  Walkthrough:
//  Intent — replace "absent collaborator" with an object of the same
//  shape that does nothing, so callers never branch on null. One `??` at
//  the top buys you an if-free body; the "does it exist?" question is
//  answered once instead of at every call site.
//  When NOT to use: when absence is *meaningful* (a missing payment
//  provider must fail loudly, not silently no-op). A null object that
//  swallows a real error is a bug factory.
//  In the wild: `console` shims in libraries, no-op metrics clients,
//  React's default context value, `Array.prototype.map` on `[]`.
//  Classic wrong turn: `logger = logger || {}` — the interface is gone,
//  and the first `logger.info(...)` explodes.

import { test, eq, ok, spy } from '../../_lib/check.js';

export function createNullLogger() {
  const noop = () => {};
  return { info: noop, warn: noop, error: noop };
}

export function runTask(task, logger) {
  const log = logger ?? createNullLogger();
  log.info(`start ${task.name}`);
  try {
    const result = task.run();
    log.info(`done ${task.name}`);
    return { ok: true, result };
  } catch (error) {
    log.error(`failed ${task.name}: ${error.message}`);
    return { ok: false, error: error.message };
  }
}

const fakeLogger = () => ({ info: spy(), warn: spy(), error: spy() });

// ──────────────────────────── tests ──────────────────────────────────────

test('the null logger implements the whole interface', () => {
  const log = createNullLogger();
  for (const method of ['info', 'warn', 'error']) {
    ok(typeof log[method] === 'function', `missing ${method}`);
    eq(log[method]('anything'), undefined);
  }
});

test('a successful task returns its result', () => {
  eq(runTask({ name: 'sync', run: () => 42 }, fakeLogger()), {
    ok: true,
    result: 42,
  });
});

test('a successful task logs start and done', () => {
  const log = fakeLogger();
  runTask({ name: 'sync', run: () => 42 }, log);
  eq(log.info.calls, [['start sync'], ['done sync']]);
  eq(log.error.callCount, 0);
});

test('a throwing task is caught, not propagated', () => {
  eq(runTask({ name: 'sync', run: () => { throw new Error('boom'); } }, fakeLogger()), {
    ok: false,
    error: 'boom',
  });
});

test('a throwing task logs through error, and never logs done', () => {
  const log = fakeLogger();
  runTask({ name: 'sync', run: () => { throw new Error('boom'); } }, log);
  eq(log.error.calls, [['failed sync: boom']]);
  eq(log.info.calls, [['start sync']]);
});

test('no logger at all still works', () => {
  eq(runTask({ name: 'quiet', run: () => 'ok' }), { ok: true, result: 'ok' });
  eq(runTask({ name: 'quiet', run: () => { throw new Error('x'); } }), {
    ok: false,
    error: 'x',
  });
});

