  const q = createQuery('users').where('age', '>', 18);
  const first = q.build();
  first.where.push({ field: 'hacked', op: '=', value: true });
  first.fields.push('secret');
  eq(q.build().where.length, 1);
  eq(q.build().fields, ['*']);
});

