  eq(history.depth(), 2);
  eq(history.undo(), true);
  eq(ed.text(), 'abc');
  eq(history.undo(), true);
  eq(ed.text(), 'ab');
  eq(history.undo(), false);
  eq(ed.text(), 'ab');
