// ──────────────────────────── tests ──────────────────────────────────────

test('building the proxy does not build the object', () => {
  const build = spy(makeClient);
  const db = lazy(build);
  ok(db !== undefined);
  eq(build.callCount, 0);
});

test('the first property read builds it, exactly once', () => {
