test('logging outside the retry hides the attempts', async () => {
  const log = spy();
  const quiet = new LoggingNotifier(new RetryingNotifier(makeSmtp(2), 3), log);
  eq(await quiet.send('a@b.c', 'hi'), { ok: true, id: 'msg-3', to: 'a@b.c' });
  eq(log.calls, [
    ['send', 'a@b.c'],
    ['ok', 'msg-3'],
  ]);
});

