  c.register('db', build);
  c.register('users', (db) => ({ db }), ['db']);
  c.register('orders', (db) => ({ db }), ['db']);

  ok(c.resolve('db') === c.resolve('db'));
  ok(c.resolve('users').db === c.resolve('orders').db);
  eq(build.callCount, 1);
});

