  const app = createOrderApp();
  app.placeOrder({ id: 'o1', customer: 'ada', totalCents: 5000 });
  throws(() => app.placeOrder({ id: 'o1', customer: 'x', totalCents: 1 }));
  throws(() => app.cancelOrder('nope'), 'unknown order: nope');
  app.cancelOrder('o1');
  throws(() => app.cancelOrder('o1'));
